package com.clavis.reader;
public class ChapterTimelineChecks {static int n;static void check(boolean b){n++;if(!b)throw new AssertionError("timeline "+n);}public static void main(String[] args){Book b=new Book("file","Book","Audio");check(b.trackStart(0)==0);check(b.trackLength(0,90000)==90000);b.chapters.add(new Book.Chapter("file","Opening",0,15000));b.chapters.add(new Book.Chapter("file","Middle",15000,60000));b.chapters.add(new Book.Chapter("file","Ending",60000,-1));check(b.chapterCount()==3);check(b.trackLength(0,90000)==15000);check(b.trackLength(1,90000)==45000);check(b.trackLength(2,90000)==30000);check(b.trackStart(1)+5000==20000);check(b.trackLength(1,30000)==15000);System.out.println(n+" chapter timeline checks passed");}}
